// newRecord shapes an enrollment from a freshly-issued token. maxTTL==0 means no
// ceiling. principal/subject are the authorizePrincipal binding and the verified
// token's Subject, stored so handleCheck's fresh-passthrough re-check can
// re-authorize (F11) without an IdP round-trip. (F11)
func newRecord(idTokenExp time.Time, refreshToken, principal, subject string, maxTTL time.Duration, now time.Time) Record {
	r := Record{Expiry: idTokenExp, RefreshToken: refreshToken, Principal: principal, Subject: subject}
	if maxTTL > 0 {
		r.Absolute = now.Add(maxTTL)
		if r.Expiry.After(r.Absolute) {
			r.Expiry = r.Absolute
		}
	}
	return r
}

// state classifies a record at time now.
