// signRequest HMAC-signs req over the canonical string and sets the three
// X-SSH-OIDC-* headers. A signed request carries NO Authorization header —
// enforced mechanically: any pre-existing Authorization header is deleted, so
// a caller reusing a request that carried one cannot put both credential
// forms on the wire (the service's signed arm ignores Authorization anyway,
// but the wire must show one mode, not both).
// nonce is RAW bytes (≥16; generated via newNonce at the call site) — NOT a
// pre-encoded base64 string: signRequest encodes exactly once, for both the
// header and the canonical string, so a pre-encoded input would double-encode
// and silently break the signature. now is the signing instant; it is embedded
// as decimal Unix seconds.
func signRequest(req *http.Request, body []byte, token string, now time.Time, nonce []byte) error {
	if len(nonce) < 16 {
		return fmt.Errorf("nonce too short: %d bytes, want ≥16", len(nonce))
	}
	req.Header.Del("Authorization")
	timestamp := strconv.FormatInt(now.Unix(), 10)
	nonceStr := base64.StdEncoding.EncodeToString(nonce)
	canonical := canonicalString(req.Method, req.URL.Path, body, timestamp, nonceStr)
	mac := hmac.New(sha256.New, []byte(token))
	mac.Write([]byte(canonical))
	req.Header.Set("X-SSH-OIDC-Signature", hex.EncodeToString(mac.Sum(nil)))
	req.Header.Set("X-SSH-OIDC-Timestamp", timestamp)
	req.Header.Set("X-SSH-OIDC-Nonce", nonceStr)
	return nil
}

